class ApiError extends Exception { public function __construct(public int $status,string $message){parent::__construct($message);} }
function fail(int $status,string $message):never {throw new ApiError($status,$message);}
function answer(array $data,int $status=200,array $headers=[]):never {http_response_code($status);foreach($headers as $h)header($h);if(function_exists('mobileAfterResponse'))mobileAfterResponse($status);echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function sql():PDO {static $db=null;if($db)return $db;if(!extension_loaded('pdo_sqlite'))fail(503,'El alojamiento no tiene SQLite activo. Contacta al administrador.');$path=__DIR__.'/database/capa.sqlite';if(!is_file($path))fail(503,'La base de datos aún no está instalada.');$db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_TIMEOUT=>8]);$db->exec('PRAGMA foreign_keys=ON; PRAGMA busy_timeout=8000');return $db;}
function run(string $query,array $values=[]):PDOStatement {$st=sql()->prepare($query);$st->execute($values);return $st;}
function one(string $query,array $values=[]):?array {$r=run($query,$values)->fetch();return $r===false?null:$r;}
function rows(string $query,array $values=[]):array {return run($query,$values)->fetchAll();}
function data():array {$raw=file_get_contents('php://input',false,null,0,300001);if(strlen($raw)>300000)fail(413,'La solicitud es demasiado grande.');try{$v=json_decode($raw,true,512,JSON_THROW_ON_ERROR);}catch(Throwable){fail(400,'Formulario inválido.');}if(!is_array($v))fail(400,'Formulario inválido.');return $v;}
function val(array $a,string $k,int $max=200,bool $required=false):string {$v=$a[$k]??'';if(!is_string($v))fail(400,'Campo inválido: '.$k);$v=trim($v);if(strlen($v)>$max||($required&&strlen($v)<2))fail(400,'Revisa el campo '.$k);return $v;}
function num(array $a,string $k,float $min,float $max):float {$v=$a[$k]??0;if(!is_numeric($v))fail(400,'Número inválido: '.$k);$n=(float)$v;if(!is_finite($n)||$n<$min||$n>$max)fail(400,'Número fuera de rango: '.$k);return $n;}
function flag(array $a,string $k):bool {if(!is_bool($a[$k]??null))fail(400,'Valor inválido: '.$k);return $a[$k];}
function secureUrl(string $url):string {if($url===''||preg_match('~^/(uploads/[a-f0-9-]+\.(png|jpg|webp)|hero\.png|hero\.webp|catalog\.png(#[0-7])?|favicon\.svg)$~',$url))return $url;if(!filter_var($url,FILTER_VALIDATE_URL)||!str_starts_with($url,'https://')||parse_url($url,PHP_URL_USER)||parse_url($url,PHP_URL_PASS))fail(400,'Usa una URL HTTPS válida.');return $url;}
function origin():void {if($_SERVER['REQUEST_METHOD']==='GET')return;if(empty($_SERVER['HTTPS'])||$_SERVER['HTTPS']==='off')fail(403,'Se requiere conexión HTTPS para enviar datos.');$host=$_SERVER['HTTP_HOST']??'';$origin=$_SERVER['HTTP_ORIGIN']??'';if($origin&&parse_url($origin,PHP_URL_HOST)!==explode(':',$host)[0])fail(403,'Origen no permitido.');if(($_SERVER['HTTP_SEC_FETCH_SITE']??'')==='cross-site')fail(403,'Solicitud no permitida.');}
function rate(string $kind,int $max,int $seconds):void {$window=(int)floor(time()/$seconds);$key=hash('sha256',($_SERVER['REMOTE_ADDR']??'unknown').':'.$kind.':'.$window);run('INSERT INTO rate_limits(k,n,expires) VALUES(?,1,?) ON CONFLICT(k) DO UPDATE SET n=n+1',[$key,($window+1)*$seconds]);if((int)one('SELECT n FROM rate_limits WHERE k=?',[$key])['n']>$max)fail(429,'Demasiados intentos. Espera unos minutos y vuelve a intentarlo.');if(random_int(1,30)===1)run('DELETE FROM rate_limits WHERE expires<?',[time()]);}
function sessionCookie(string $token,int $age):void {$secure=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';setcookie('capa_session',$token,['expires'=>time()+$age,'path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Strict']);}
function admin():array {if(defined('CAPA_MOBILE_REQUEST'))return mobileAdmin();$token=$_COOKIE['capa_session']??'';if(strlen($token)<20)fail(401,'Inicia sesión para continuar.');$user=one('SELECT a.id,a.email FROM sessions s JOIN admins a ON a.id=s.admin_id WHERE s.token_hash=? AND s.expires_at>?',[hash('sha256',$token),time()]);if(!$user)fail(401,'Tu sesión ha caducado. Vuelve a iniciar sesión.');return $user;}
function userOrNull():?array {try{return admin();}catch(ApiError){return null;}}
function maintenanceEnabled():bool {return is_file(__DIR__.'/maintenance.flag');}
function setMaintenance(bool $enabled):void {$path=__DIR__.'/maintenance.flag';if($enabled){if(file_put_contents($path,'on',LOCK_EX)===false)fail(503,'No se pudo activar el mantenimiento.');chmod($path,0644);}elseif(is_file($path)&&!unlink($path))fail(503,'No se pudo quitar el mantenimiento.');}
function ensureCustomerSchema():void {sql()->exec('CREATE TABLE IF NOT EXISTS customer_accounts(id TEXT PRIMARY KEY,contact_type TEXT NOT NULL,contact TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL)');sql()->exec('CREATE TABLE IF NOT EXISTS customer_sessions(token_hash TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customer_accounts(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL)');sql()->exec('CREATE TABLE IF NOT EXISTS customer_orders(order_id INTEGER PRIMARY KEY REFERENCES orders(id) ON DELETE CASCADE,customer_id TEXT NOT NULL REFERENCES customer_accounts(id) ON DELETE CASCADE)');sql()->exec('CREATE INDEX IF NOT EXISTS idx_customer_orders_customer ON customer_orders(customer_id)');}
function customerContact(string $input):array {$input=trim($input);if(str_contains($input,'@')){$contact=strtolower($input);if(strlen($contact)>200||!filter_var($contact,FILTER_VALIDATE_EMAIL))fail(400,'Escribe un correo válido.');return ['email',$contact];}if(!preg_match('/^[+\d\s().-]+$/',$input))fail(400,'Escribe un teléfono válido.');$contact=preg_replace('/\D+/','',$input);if(strlen($contact)<10||strlen($contact)>15)fail(400,'Escribe un teléfono de 10 a 15 dígitos.');return ['phone',$contact];}
function customerCookie(string $token,int $age):void {$secure=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';setcookie('capa_customer',$token,['expires'=>time()+$age,'path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Lax']);}
function customerOrNull():?array {$token=$_COOKIE['capa_customer']??'';if(strlen($token)<20)return null;return one('SELECT a.id,a.contact_type,a.contact FROM customer_sessions s JOIN customer_accounts a ON a.id=s.customer_id WHERE s.token_hash=? AND s.expires_at>?',[hash('sha256',$token),time()]);}
function customer():array {$account=customerOrNull();if(!$account)fail(401,'Inicia sesión para ver tus pedidos.');return $account;}
function customerOrder(array $order):array {$d=json_decode($order['data'],true);$h=rows('SELECT status,created_at date FROM order_history WHERE order_id=? ORDER BY id',[$order['id']]);return ['folio'=>'3D-'.str_pad((string)$order['id'],6,'0',STR_PAD_LEFT),'status'=>$order['status'],'productName'=>$d['productName'],'total'=>$d['total'],'quantity'=>(int)$order['quantity'],'createdAt'=>$order['created_at'],'image'=>$d['image']??'','history'=>$h];}
function ensureConversationSchema():void {ensureCustomerSchema();sql()->exec('CREATE TABLE IF NOT EXISTS order_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,sender TEXT NOT NULL CHECK(sender IN (\'admin\',\'customer\')),body TEXT NOT NULL,created_at TEXT NOT NULL)');sql()->exec('CREATE INDEX IF NOT EXISTS idx_order_messages_order ON order_messages(order_id,id)');sql()->exec('CREATE TABLE IF NOT EXISTS push_subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT,endpoint_hash TEXT NOT NULL,endpoint TEXT NOT NULL,customer_id TEXT REFERENCES customer_accounts(id) ON DELETE CASCADE,order_id INTEGER REFERENCES orders(id) ON DELETE CASCADE,created_at TEXT NOT NULL,UNIQUE(endpoint_hash,customer_id,order_id))');sql()->exec('CREATE INDEX IF NOT EXISTS idx_push_order ON push_subscriptions(order_id)');sql()->exec('CREATE INDEX IF NOT EXISTS idx_push_customer ON push_subscriptions(customer_id)');}
function clientOrder(array $body):array {$folio=val($body,'folio',20,true);if(!preg_match('/^3D-(\d{6,})$/',$folio,$m))fail(400,'Folio inválido.');$order=one('SELECT * FROM orders WHERE id=?',[(int)$m[1]]);if(!$order)fail(404,'Pedido no encontrado.');$account=customerOrNull();if($account&&one('SELECT order_id FROM customer_orders WHERE order_id=? AND customer_id=?',[$order['id'],$account['id']]))return $order;$token=val($body,'token',100);if(strlen($token)<20||!hash_equals($order['token_hash'],hash('sha256',$token)))fail(403,'No tienes acceso a este pedido.');return $order;}
function vapidKeys():array {$file=__DIR__.'/database/vapid.json';if(is_file($file)){$keys=json_decode((string)file_get_contents($file),true);if(is_array($keys)&&isset($keys['private'],$keys['public']))return $keys;}if(!function_exists('openssl_pkey_new'))fail(503,'Las notificaciones no están disponibles en este servidor.');$key=openssl_pkey_new(['private_key_type'=>OPENSSL_KEYTYPE_EC,'curve_name'=>'prime256v1']);if(!$key||!openssl_pkey_export($key,$pem))fail(503,'No se pudieron preparar las notificaciones.');$details=openssl_pkey_get_details($key);$ec=$details['ec']??[];if(!isset($ec['x'],$ec['y']))fail(503,'No se pudo preparar la clave pública.');$keys=['private'=>$pem,'public'=>base64url("\x04".$ec['x'].$ec['y'])];if(file_put_contents($file,json_encode($keys),LOCK_EX)===false)fail(503,'No se pudieron guardar las claves de notificación.');chmod($file,0600);return $keys;}
function base64url(string $s):string {return rtrim(strtr(base64_encode($s),'+/','-_'),'=');}
function pushEndpoint(string $url):string {$p=parse_url($url);$host=strtolower($p['host']??'');$allowed=['fcm.googleapis.com','fcm-xm.googleapis.com','updates.push.services.mozilla.com','web.push.apple.com','push.services.mozilla.com','wns2-par02p.notify.windows.com'];if(($p['scheme']??'')!=='https'||!in_array($host,$allowed,true)||isset($p['user'])||isset($p['pass'])||isset($p['port'])||strlen($url)>2048)fail(400,'El navegador devolvió una suscripción de notificaciones no admitida.');return $url;}
function derToJose(string $der):string {$pos=2;if(ord($der[1])&128)$pos=2+(ord($der[1])&127);$parts=[];for($i=0;$i<2;$i++){if(ord($der[$pos++])!==2)throw new RuntimeException('Firma VAPID inválida');$len=ord($der[$pos++]);$parts[]=str_pad(substr(ltrim(substr($der,$pos,$len),"\x00"),-32),32,"\x00",STR_PAD_LEFT);$pos+=$len;}return $parts[0].$parts[1];}
function sendPushForOrder(int $orderId):void {try{ensureConversationSchema();$subs=rows('SELECT DISTINCT endpoint FROM push_subscriptions WHERE order_id=? OR customer_id IN (SELECT customer_id FROM customer_orders WHERE order_id=?) LIMIT 20',[$orderId,$orderId]);if(!$subs||!function_exists('curl_init'))return;$keys=vapidKeys();foreach($subs as $sub){$url=$sub['endpoint'];try{$url=pushEndpoint($url);$p=parse_url($url);$aud='https://'.$p['host'];$head=base64url('{"typ":"JWT","alg":"ES256"}');$claims=base64url(json_encode(['aud'=>$aud,'exp'=>time()+3600,'sub'=>'https://capa3d.site.je']));$input=$head.'.'.$claims;if(!openssl_sign($input,$der,$keys['private'],OPENSSL_ALGO_SHA256))continue;$jwt=$input.'.'.base64url(derToJose($der));$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>'',CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>2,CURLOPT_TIMEOUT=>4,CURLOPT_HTTPHEADER=>['Authorization: vapid t='.$jwt.', k='.$keys['public'],'TTL: 3600','Content-Length: 0']]);curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if(in_array($status,[404,410],true))run('DELETE FROM push_subscriptions WHERE endpoint_hash=?',[hash('sha256',$url)]);}catch(Throwable $e){error_log('CAPA 3D push: '.$e->getMessage());}}}catch(Throwable $e){error_log('CAPA 3D push: '.$e->getMessage());}}
