if(is_file(__DIR__.'/mobile-support.php'))require_once __DIR__.'/mobile-support.php';
function passhash(string $password,string $salt):string {return hash_pbkdf2('sha256',$password,$salt,100000,64);}
function thumbnailUpload(string $file):void {
 if(!function_exists('imagecreatefromstring')||!function_exists('imagewebp'))return;
 $info=@getimagesize($file);if(!$info||$info[0]<1||$info[1]<1||$info[0]*$info[1]>12000000)return;
 $bytes=@file_get_contents($file);if(!is_string($bytes))return;
 $source=@imagecreatefromstring($bytes);if(!$source)return;
 $width=min(600,imagesx($source));$height=max(1,(int)round(imagesy($source)*$width/imagesx($source)));
 $thumb=imagecreatetruecolor($width,$height);imagealphablending($thumb,false);imagesavealpha($thumb,true);imagefill($thumb,0,0,imagecolorallocatealpha($thumb,0,0,0,127));
 imagecopyresampled($thumb,$source,0,0,0,0,$width,$height,imagesx($source),imagesy($source));
 $dir=__DIR__.'/uploads/thumbs';if((is_dir($dir)||@mkdir($dir,0755,true))&&is_writable($dir)){$target=$dir.'/opt-'.pathinfo($file,PATHINFO_FILENAME).'.webp';if(@imagewebp($thumb,$target,75))@chmod($target,0644);}
 imagedestroy($thumb);imagedestroy($source);
}
function writeFile():array {if(!isset($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)fail(400,'Selecciona una imagen.');$f=$_FILES['file'];if($f['size']>5*1024*1024)fail(413,'La imagen debe pesar menos de 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$formats=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];if(!isset($formats[$mime]))fail(400,'Formato no válido. Usa PNG, JPEG o WebP.');$dir=__DIR__.'/uploads';if(!is_dir($dir)&&!mkdir($dir,0755,true))fail(503,'No se pudo preparar el almacenamiento.');$name=bin2hex(random_bytes(16)).'.'.$formats[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))fail(503,'No se pudo guardar la imagen.');chmod($dir.'/'.$name,0644);thumbnailUpload($dir.'/'.$name);return ['url'=>'/uploads/'.$name];}
function settings():array {$r=one("SELECT data FROM settings WHERE id='store'");return $r?json_decode($r['data'],true):[];}
function categories(bool $onlyActive=false):array {return array_map(fn($r)=>json_decode($r['data'],true),rows('SELECT data FROM categories'.($onlyActive?' WHERE active=1':'').' ORDER BY sort'));}
function products(bool $all=false):array {
 $rr=rows('SELECT * FROM products'.($all?'':' WHERE published=1').' ORDER BY created_at DESC');
 $images=[];foreach(rows('SELECT product_id,url FROM product_images ORDER BY sort') as $image)$images[$image['product_id']][]=$image['url'];
 $popularity=[];foreach(rows("SELECT product_id,SUM(quantity) n FROM orders WHERE status!='Cancelado' GROUP BY product_id") as $row)$popularity[$row['product_id']]=(int)$row['n'];
 $out=[];foreach($rr as $r){$p=json_decode($r['data'],true);$p['id']=$r['id'];$p['name']=$r['name'];$p['categoryId']=$r['category_id']??'';$p['price']=$r['price']/100;$p['stock']=(int)$r['stock'];$p['unlimited']=(bool)$r['unlimited'];$p['published']=(bool)$r['published'];$p['status']=$r['status'];$p['createdAt']=$r['created_at'];$p['images']=$images[$r['id']]??[];$p['popularity']=$popularity[$r['id']]??0;$out[]=$p;}
 return $out;
}
function orders():array {$h=rows('SELECT * FROM order_history ORDER BY id');return array_map(function($r)use($h){$o=json_decode($r['data'],true);$o['id']=(int)$r['id'];$o['folio']='3D-'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT);$o['type']=$r['type'];$o['productId']=$r['product_id']??'';$o['quantity']=(int)$r['quantity'];$o['status']=$r['status'];$o['createdAt']=$r['created_at'];$o['history']=array_values(array_map(fn($x)=>['date'=>$x['created_at'],'status'=>$x['status'],'note'=>$x['note']],array_filter($h,fn($x)=>$x['order_id']==$r['id'])));return $o;},rows('SELECT * FROM orders ORDER BY id DESC'));}
function active(array $p):bool {return $p['status']==='Disponible'&&($p['unlimited']||$p['stock']>0);}
function validProduct(array $p):array {foreach(['name'=>150,'description'=>5000,'categoryId'=>80,'subcategory'=>200,'dimensions'=>200,'material'=>100,'colors'=>300,'fabrication'=>100,'delivery'=>100,'sku'=>80,'extra'=>3000] as $k=>$m)val($p,$k,$m,$k==='name');foreach(['price','oldPrice'] as $k)num($p,$k,0,1000000);foreach(['stock','lowStock'] as $k){$n=num($p,$k,0,1000000);if($n!=(int)$n)fail(400,'El stock debe ser entero.');}foreach(['offer','unlimited','featured','isNew','recommended','published'] as $k)flag($p,$k);if(!in_array($p['status']??'', ['Disponible','Agotado','Próximamente'],true)||!in_array($p['size']??'', ['Pequeño','Mediano','Grande'],true))fail(400,'Estado o tamaño inválido.');if($p['offer']&&$p['oldPrice']<=$p['price'])fail(400,'El precio anterior debe superar al precio de oferta.');if(!is_array($p['images']??null)||count($p['images'])>12||($p['published']&&count($p['images'])===0))fail(400,'Añade una imagen antes de publicar.');foreach($p['images'] as $url)secureUrl($url);if($p['categoryId']&&!one('SELECT id FROM categories WHERE id=?',[$p['categoryId']]))fail(400,'Categoría inválida.');return $p;}
function validCategory(array $c):array {val($c,'name',100,true);val($c,'description',1000);val($c,'icon',50);secureUrl(val($c,'image',2048));flag($c,'active');num($c,'sort',0,10000);return $c;}
function filamentProfiles():array {$r=one("SELECT data FROM settings WHERE id='filament-profiles'");$profiles=$r?json_decode($r['data'],true):[];return is_array($profiles)?$profiles:[];}
function validFilamentProfile(array $p):array {$id=val($p,'id',80,true);if(!preg_match('/^[a-f0-9-]{36}$/i',$id))fail(400,'Identificador de filamento inválido.');$name=val($p,'name',80,true);$color=val($p,'color',7,true);if(!preg_match('/^#[0-9a-fA-F]{6}$/',$color))fail(400,'Selecciona un color válido.');$spoolCost=num($p,'spoolCost',0.01,1000000);$spoolGrams=num($p,'spoolGrams',1,100000);return ['id'=>$id,'name'=>$name,'color'=>$color,'spoolCost'=>$spoolCost,'spoolGrams'=>$spoolGrams];}
function validSettings(array $s):array {foreach(['name'=>100,'phone'=>30,'whatsapp'=>20,'address'=>300,'hours'=>200,'delivery'=>1000,'heroTitle'=>150,'heroDescription'=>600,'banner'=>200] as $k=>$m)val($s,$k,$m,$k==='name'||$k==='heroTitle');foreach(['logo','favicon','heroImage'] as $k)secureUrl(val($s,$k,2048));foreach(['instagram','facebook'] as $k){$v=val($s,$k,2048);if($v)secureUrl($v);}if(!preg_match('/^#[0-9a-fA-F]{6}$/',$s['primaryColor']??''))fail(400,'Color inválido.');if(!preg_match('/^[+\d\s-]*$/',$s['whatsapp']))fail(400,'WhatsApp inválido.');flag($s,'hideSoldOut');flag($s,'customEnabled');return $s;}
function makerworldUrl(string $url):int {$parts=parse_url($url);if(!$parts||($parts['scheme']??'')!=='https'||!in_array(strtolower($parts['host']??''),['makerworld.com','www.makerworld.com'],true)||isset($parts['user'])||isset($parts['pass'])||!preg_match('~^/(?:[a-z]{2}/)?models/(\d+)(?:[-/]|$)~i',$parts['path']??'',$m))fail(400,'Pega el enlace HTTPS de un modelo de MakerWorld.');return (int)$m[1];}
function makerworldImage(string $url):bool {$parts=parse_url($url);return $parts&&($parts['scheme']??'')==='https'&&in_array(strtolower($parts['host']??''),['makerworld.bblmw.com','public-cdn.bblmw.com'],true)&&empty($parts['user'])&&empty($parts['pass']);}
function makerworldImport(string $url):array {
 $modelId=makerworldUrl($url);$id='mw-'.$modelId;$existing=one('SELECT id FROM products WHERE id=?',[$id]);if($existing){foreach(products(true) as $p)if($p['id']===$id)return ['product'=>$p,'alreadyExists'=>true];}
 $endpoint='https://api.bambulab.com/v1/design-service/design/'.$modelId;
 $ch=curl_init($endpoint);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>18,CURLOPT_MAXREDIRS=>0,CURLOPT_USERAGENT=>'CAPA3D/1.0',CURLOPT_HTTPHEADER=>['Accept: application/json']]);$raw=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);
 if($status!==200||!is_string($raw)||strlen($raw)>1500000)fail(502,'MakerWorld no devolvió los datos del modelo. Intenta más tarde.');$m=json_decode($raw,true);if(!is_array($m)||($m['id']??null)!==$modelId)fail(502,'No se pudo validar la respuesta de MakerWorld.');
 $license=trim((string)($m['license']??''))?:'No indicada';
 $title=trim((string)($m['title']??''));$description=trim(preg_replace('/\s+/u',' ',html_entity_decode(strip_tags((string)($m['summary']??'')),ENT_QUOTES|ENT_HTML5,'UTF-8'))??'');if(strlen($title)<2||strlen($title)>150||$description==='')fail(502,'MakerWorld no devolvió un título o descripción válidos.');$description=substr($description,0,5000);
 $images=[];$candidates=[$m['coverUrl']??''];foreach(array_slice($m['instances']??[],0,6) as $instance){foreach(array_slice($instance['pictures']??[],0,3) as $picture)$candidates[]=$picture['url']??'';}
 foreach($candidates as $image){if(is_string($image)&&makerworldImage($image)&&!in_array($image,$images,true))$images[]=$image;if(count($images)>=12)break;}if(!$images)fail(502,'MakerWorld no devolvió imágenes válidas.');
 $category=one('SELECT id FROM categories WHERE active=1 ORDER BY sort LIMIT 1');if(!$category)fail(409,'Crea una categoría activa antes de importar.');$creator=trim((string)($m['designCreator']['name']??''));$source='https://makerworld.com/es/models/'.$modelId.'-'.($m['slug']??'modelo');$extra="Fuente: $source\nLicencia: $license".($creator!==''?"\nDiseñador: $creator":'');
 $now=gmdate('c');$p=['id'=>$id,'name'=>$title,'description'=>$description,'price'=>0,'oldPrice'=>0,'offer'=>false,'categoryId'=>$category['id'],'subcategory'=>'','dimensions'=>'','size'=>'Mediano','material'=>'PLA','colors'=>'','fabrication'=>'2–3 días','delivery'=>'3–5 días hábiles','sku'=>'MW-'.$modelId,'status'=>'Próximamente','stock'=>0,'unlimited'=>true,'lowStock'=>3,'featured'=>false,'isNew'=>true,'recommended'=>false,'published'=>false,'extra'=>$extra,'images'=>$images,'createdAt'=>$now,'popularity'=>0];validProduct($p);
 $pdo=sql();$pdo->exec('BEGIN IMMEDIATE');try{run('INSERT INTO products(id,name,category_id,price,stock,unlimited,published,status,data,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',[$id,$title,$category['id'],0,0,1,0,'Próximamente',json_encode($p,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),$now]);foreach($images as $i=>$image)run('INSERT INTO product_images(id,product_id,url,sort) VALUES(?,?,?,?)',[bin2hex(random_bytes(16)),$id,$image,$i]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
 return ['product'=>$p,'alreadyExists'=>false];
}
function apiDispatch():void {try {
